<?php
require __DIR__.'/includes/bootstrap.php';$user=require_user(true);require __DIR__.'/includes/modules.php';require __DIR__.'/includes/layout.php';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();try{transaction(function()use($user){
 $action=text_value($_POST,'action',20,true);
 if($action==='create'){$name=text_value($_POST,'full_name',160,true);$email=email_value(text_value($_POST,'email',190,true));$role=enum_value($_POST['role']??'',['admin','super_admin']);$password=hash_password(text_value($_POST,'password',72,true));if(query('SELECT id FROM admin_users WHERE email=?',[$email])->fetchColumn())throw new ValidationError('A staff account already uses that email.');query('INSERT INTO admin_users(full_name,email,password_hash,role) VALUES(?,?,?,?)',[$name,$email,$password,$role]);audit('admin_created','admin_users',(int)db()->lastInsertId());}
 elseif($action==='update'){
  $id=id_value($_POST['id']??'');$supers=query("SELECT id FROM admin_users WHERE role='super_admin' AND active=1 ORDER BY id FOR UPDATE")->fetchAll(PDO::FETCH_COLUMN);$target=query('SELECT * FROM admin_users WHERE id=? FOR UPDATE',[$id])->fetch();if(!$target)throw new ValidationError('Account not found.');$role=enum_value($_POST['role']??'',['admin','super_admin']);$active=enum_value($_POST['active']??'',['0','1']);
  if($id===(int)$user['id']&&($active==='0'||$role!=='super_admin'))throw new ValidationError('You cannot disable or demote your own account.');
  if($target['role']==='super_admin'&&$target['active']&&count($supers)<=1&&($active==='0'||$role!=='super_admin'))throw new ValidationError('Keep at least one active Super Admin.');
  query('UPDATE admin_users SET role=?,active=?,auth_version=auth_version+1 WHERE id=?',[$role,$active,$id]);audit($active==='0'?'admin_disabled':'admin_permissions_updated','admin_users',$id);
 }else throw new ValidationError('Invalid action.');
});$_SESSION['flash']='Staff account saved.';redirect('admin/users.php');}catch(ValidationError $ex){$error=$ex->getMessage();}}
page_header('Admin users',$user);if($error)echo '<p class="notice error">'.e($error).'</p>';echo '<section class="panel"><h2>Create staff account</h2><form method="post">'.csrf_input().'<input type="hidden" name="action" value="create"><div class="grid">';input_field('full_name','Full name','','text',true);input_field('email','Email','','email',true);input_field('password','Initial password (12–72 bytes)','','password',true);select_field('role','Role',['admin','super_admin'],'admin');echo '</div><button>Create account</button></form><p class="muted">Share initial credentials securely. Staff can change their password immediately. No default accounts are shipped.</p></section><div class="table-wrap" tabindex="0" role="region" aria-label="Scrollable records"><table><thead><tr><th>Name</th><th>Email</th><th>Permissions</th></tr></thead><tbody>';
$page=max(1,(int)($_GET['page']??1));foreach(query('SELECT id,full_name,email,role,active FROM admin_users ORDER BY id LIMIT 25 OFFSET '.(($page-1)*25))->fetchAll() as $u){echo '<tr><td>'.e($u['full_name']).'</td><td>'.e($u['email']).'</td><td><form method="post" class="inline-form">'.csrf_input().'<input type="hidden" name="action" value="update"><input type="hidden" name="id" value="'.(int)$u['id'].'">';select_field('role','Role',['admin','super_admin'],$u['role']);select_field('active','Account state',['0'=>'Disabled','1'=>'Active'],(string)$u['active']);echo '<button>Save permissions</button></form></td></tr>';}echo '</tbody></table></div><p><a href="?page='.($page+1).'">Next page</a></p>';page_footer();
